import type { DesignLibraryReference } from '../../types/design-library';

type MatchKind = 'title' | 'title_phrase' | 'content_phrase' | 'terms';
interface SavedMatch {
  reference: DesignLibraryReference;
  kind: MatchKind;
  titleTerms: number;
}

const MATCH_ORDER: Record<MatchKind, number> = {
  title: 0,
  title_phrase: 1,
  content_phrase: 2,
  terms: 3,
};
const MIN_PHRASE_TERMS = 2;

const words = (text: string): string[] =>
  text.toLocaleLowerCase().match(/[\p{L}\p{N}]+/gu) ?? [];

const containsPhrase = (text: string[], phrase: string) =>
  ` ${text.join(' ')} `.includes(` ${phrase} `);

export const rankReferenceMatches = ({
  query,
  references,
  semanticMatches = [],
}: {
  query: string;
  references: DesignLibraryReference[];
  semanticMatches?: DesignLibraryReference[];
}): DesignLibraryReference[] => {
  const queryWords = words(query);
  const terms = [...new Set(queryWords)];
  const phrase = queryWords.join(' ');
  const semanticRanks = new Map(
    semanticMatches.map((reference, rank) => [reference.id, rank]),
  );
  const matches = references
    .flatMap((reference): SavedMatch[] => {
      const title = words(reference.title);
      const content = [
        reference.text,
        reference.note ?? '',
        reference.observation?.description ?? '',
      ].map(words);
      const savedWords = new Set([...title, ...content.flat()]);
      if (!terms.length || !terms.every((term) => savedWords.has(term)))
        return [];
      let kind: MatchKind = 'terms';
      if (title.join(' ') === phrase) kind = 'title';
      else if (queryWords.length >= MIN_PHRASE_TERMS) {
        if (containsPhrase(title, phrase)) kind = 'title_phrase';
        else if (content.some((text) => containsPhrase(text, phrase)))
          kind = 'content_phrase';
      }
      return [
        {
          reference,
          kind,
          titleTerms: terms.filter((term) => title.includes(term)).length,
        },
      ];
    })
    .sort(
      (left, right) =>
        MATCH_ORDER[left.kind] - MATCH_ORDER[right.kind] ||
        (semanticRanks.get(left.reference.id) ?? Number.MAX_SAFE_INTEGER) -
          (semanticRanks.get(right.reference.id) ?? Number.MAX_SAFE_INTEGER) ||
        right.titleTerms - left.titleTerms ||
        left.reference.id.localeCompare(right.reference.id),
    );
  const ranked = [
    ...matches
      .filter(({ kind }) => kind !== 'terms')
      .map(({ reference }) => reference),
    ...semanticMatches,
    ...matches
      .filter(({ kind }) => kind === 'terms')
      .map(({ reference }) => reference),
  ];
  return [
    ...new Map(ranked.map((reference) => [reference.id, reference])).values(),
  ];
};
